// Ported nearly as-is from the legacy index.html inline <script> for the
// "Estimación de Valor de Mercado" tool (originally index.html lines
// ~1960-2772). Injected into the page as a real classic script (via
// ValuacionTool.jsx) instead of being rewritten in React, so this 800+
// line calculator keeps behaving exactly like it did before.
//
// Wrapped in an IIFE (not present in the original) so the component can
// safely inject this script again if it remounts (e.g. client-side
// navigation away and back) without "Identifier has already been declared"
// on the original's top-level `let`s. The functions the shell HTML's
// inline onclick/oninput/onchange handlers need are re-exposed on
// `window` explicitly at the end instead.
//
// Exported as a JSON-escaped string (not a template literal) because the
// script itself contains many backticks/template literals of its own.
export const valuacionScriptSrc = "(function () {\n\n// STATE\nlet tipoInmueble = 'casa';\nlet metodo = 'promedio';\nlet pesoTerreno = 50; // % para terreno en método peso ajustable\nlet factorNeg = 8;    // % factor de negociación\nlet sigmaThresh = 1.5;\nlet outlierMetric = 'construccion';\nlet comparables = [];\nlet compIdCounter = 0;\nlet propEquip = { alberca: false, roof: false, elevador: false, cine: false };\n\n// INIT\ndocument.addEventListener('DOMContentLoaded', () => {\n  const today = new Date();\n  document.getElementById('p_fecha').value =\n    today.toLocaleDateString('es-MX', { day: 'numeric', month: 'long', year: 'numeric' });\n  for (let i = 0; i < 4; i++) addComp();\n  updateCompCount();\n  updateFactorNeg();\n});\n\n// TIPO DE INMUEBLE\nfunction setTipo(tipo, btn) {\n  tipoInmueble = tipo;\n  document.querySelectorAll('#tipoSeg button').forEach(b => b.classList.remove('active'));\n  btn.classList.add('active');\n  document.getElementById('g_terreno').style.display = tipo !== 'depto' ? '' : 'none';\n  document.getElementById('g_construccion').style.display = tipo !== 'terreno' ? '' : 'none';\n  calcPropValues();\n  updateAllComps();\n}\n\nfunction setEquip(key, val, btn) {\n  propEquip[key] = val;\n  const parent = btn.closest('.seg-control');\n  parent.querySelectorAll('button').forEach(b => b.classList.remove('active'));\n  btn.classList.add('active');\n}\n\nfunction calcPropValues() {\n  const precio = parseFloat(document.getElementById('p_precio_prop').value) || 0;\n  const terreno = parseFloat(document.getElementById('p_terreno').value) || 0;\n  const const_ = parseFloat(document.getElementById('p_construccion').value) || 0;\n  const fmt = v => v > 0 ? '$' + Math.round(v).toLocaleString('es-MX') : '—';\n  document.getElementById('p_ppm_terreno').textContent =\n    tipoInmueble !== 'depto' && terreno > 0 ? fmt(precio / terreno) : '—';\n  document.getElementById('p_ppm_const').textContent =\n    tipoInmueble !== 'terreno' && const_ > 0 ? fmt(precio / const_) : '—';\n}\n\n// MÉTODO DE VALUACIÓN\nfunction setMetodo(m) {\n  metodo = m;\n  ['promedio','peso'].forEach(opt => {\n    const card = document.getElementById(`mOpt_${opt}`);\n    const dot = document.getElementById(`mDot_${opt}`);\n    if (opt === m) {\n      card.style.border = '2px solid var(--orange)';\n      card.style.background = 'var(--orange-pale)';\n      dot.style.background = 'white';\n      dot.parentElement.style.background = 'var(--orange)';\n      dot.parentElement.style.border = 'none';\n    } else {\n      card.style.border = '2px solid var(--gray-200)';\n      card.style.background = 'white';\n      dot.style.background = 'transparent';\n      dot.parentElement.style.background = 'transparent';\n      dot.parentElement.style.border = '2px solid var(--gray-400)';\n    }\n  });\n  document.getElementById('pesoSliderWrap').style.display = m === 'peso' ? 'block' : 'none';\n}\n\nfunction updatePeso(val) {\n  pesoTerreno = parseInt(val);\n  const pc = 100 - pesoTerreno;\n  document.getElementById('pesoFillT').style.width = pesoTerreno + '%';\n  document.getElementById('pesoTLabel').textContent = pesoTerreno + '%';\n  document.getElementById('pesoCLabel').textContent = pc + '%';\n}\n\n// FACTOR DE NEGOCIACIÓN\nfunction updateFactorNeg() {\n  factorNeg = parseFloat(document.getElementById('factorNeg').value);\n  document.getElementById('factorNegLabel').textContent = factorNeg + '%';\n  const mult = (factorNeg / 100);\n  document.getElementById('prev_salida').textContent = `VM × ${(1 + mult).toFixed(2)}`;\n  document.getElementById('prev_cierre').textContent = `VM × ${(1 - mult).toFixed(2)}`;\n}\nfunction setFactorNeg(v) {\n  document.getElementById('factorNeg').value = v;\n  updateFactorNeg();\n}\n\n// SIGMA / OUTLIER\nfunction updateSigma() {\n  sigmaThresh = parseFloat(document.getElementById('sigmaThresh').value);\n  document.getElementById('sigmaValLabel').textContent = sigmaThresh + 'σ';\n  document.getElementById('sigmaLabel').textContent = sigmaThresh + 'σ';\n}\nfunction setOutlierMetric(m, btn) {\n  outlierMetric = m;\n  document.querySelectorAll('#outlierMetricSeg button').forEach(b => b.classList.remove('active'));\n  btn.classList.add('active');\n}\n\n// COMPARABLES\nfunction addComp() {\n  if (comparables.length >= 6) return;\n  const id = ++compIdCounter;\n  comparables.push({ id, atypical: false, outlierFlag: false, confianza: 'portal_rec' });\n  renderComp(id);\n  updateCompCount();\n  if (comparables.length >= 6) document.getElementById('addCompBtn').style.display = 'none';\n}\n\nfunction renderComp(id) {\n  const idx = comparables.findIndex(c => c.id === id);\n  const n = idx + 1;\n  const existing = document.getElementById(`comp_${id}`);\n  const comp = comparables[idx];\n  const showT = tipoInmueble !== 'depto';\n  const showC = tipoInmueble !== 'terreno';\n\n  // Equipamientos del comparable\n  const equips = ['alberca','roof','elevador','cine'];\n  const equipLabels = { alberca:'Alberca', roof:'Roof garden', elevador:'Elevador', cine:'Cine/HT' };\n\n  const html = `\n<div class=\"comp-card ${comp.atypical?'atypical':''} ${comp.outlierFlag&&!comp.atypical?'outlier-flag':''}\" id=\"comp_${id}\">\n  <div class=\"comp-header\">\n    <div class=\"comp-title-row\">\n      <div class=\"comp-num ${comp.atypical?'atypical-num':comp.outlierFlag?'outlier-num':''}\">${n}</div>\n      <span style=\"font-size:12px;font-weight:600;color:var(--navy-mid)\" id=\"c${id}_ppm_display\">—</span>\n      ${comp.atypical ? '<span class=\"badge-sm badge-red\">Excluido</span>' : ''}\n      ${comp.outlierFlag && !comp.atypical ? '<span class=\"badge-sm badge-amber\">⚠ Revisar — fuera de rango estadístico</span>' : ''}\n      <span id=\"c${id}_weight_display\" class=\"weight-chip\" style=\"margin-left:4px\"></span>\n    </div>\n    <div style=\"display:flex;align-items:center;gap:10px\">\n      <label class=\"atypical-toggle\">\n        <input type=\"checkbox\" ${comp.atypical?'checked':''} onchange=\"toggleAtypical(${id},this.checked)\">\n        Excluir del promedio\n      </label>\n      ${comparables.length > 1 ? `<button onclick=\"removeComp(${id})\" style=\"background:none;border:none;cursor:pointer;color:var(--gray-400);font-size:16px;padding:0 4px\">×</button>` : ''}\n    </div>\n  </div>\n  <div class=\"comp-body\">\n    <div class=\"form-grid-5\" style=\"margin-bottom:10px\">\n      <div class=\"ov-form-group span-2\">\n        <label>Enlace del anuncio</label>\n        <input type=\"url\" id=\"c${id}_url\" placeholder=\"https://inmuebles24.com/…\" value=\"${comp.url||''}\">\n      </div>\n      <div class=\"ov-form-group\">\n        <label>Precio de lista ($MXN)</label>\n        <div class=\"input-prefix-wrap\"><span class=\"input-prefix\">$</span>\n          <input type=\"number\" id=\"c${id}_precio\" placeholder=\"0\" min=\"0\" value=\"${comp.precio||''}\">\n        </div>\n      </div>\n      <div class=\"ov-form-group\">\n        <label>Fuente / portal</label>\n        <select id=\"c${id}_fuente\" onchange=\"updateCompCalc(${id})\">\n          <option value=\"\">Fuente…</option>\n          <option value=\"Inmuebles24\" ${comp.fuente==='Inmuebles24'?'selected':''}>Inmuebles24</option>\n          <option value=\"Vivanuncios\" ${comp.fuente==='Vivanuncios'?'selected':''}>Vivanuncios</option>\n          <option value=\"Lamudi\" ${comp.fuente==='Lamudi'?'selected':''}>Lamudi</option>\n          <option value=\"MexListings\" ${comp.fuente==='MexListings'?'selected':''}>MexListings</option>\n          <option value=\"asesor_directo\" ${comp.fuente==='asesor_directo'?'selected':''}>Asesor directo</option>\n          <option value=\"Otro\" ${comp.fuente==='Otro'?'selected':''}>Otro</option>\n        </select>\n      </div>\n      <div class=\"ov-form-group\">\n        <label>Confianza</label>\n        <select id=\"c${id}_confianza\" onchange=\"updateCompCalc(${id})\">\n          <option value=\"verificado\" ${comp.confianza==='verificado'?'selected':''}>Verificado / directo</option>\n          <option value=\"portal_ver\" ${comp.confianza==='portal_ver'?'selected':''}>Portal — lo conozco</option>\n          <option value=\"portal_rec\" ${comp.confianza==='portal_rec'?'selected':''}>Portal — reciente</option>\n          <option value=\"portal_vie\" ${comp.confianza==='portal_vie'?'selected':''}>Portal — sin verificar</option>\n        </select>\n      </div>\n    </div>\n    <div class=\"form-grid-5\" style=\"margin-bottom:10px\">\n      ${showT ? `<div class=\"ov-form-group\"><label>Terreno (m²)</label><input type=\"number\" id=\"c${id}_terreno\" placeholder=\"0\" min=\"0\" value=\"${comp.terreno||''}\"></div>` : '<div></div>'}\n      ${showC ? `<div class=\"ov-form-group\"><label>Construcción (m²)</label><input type=\"number\" id=\"c${id}_construccion\" placeholder=\"0\" min=\"0\" value=\"${comp.construccion||''}\"></div>` : '<div></div>'}\n      <div class=\"ov-form-group\"><label>Recámaras</label><input type=\"number\" id=\"c${id}_recamaras\" placeholder=\"—\" min=\"0\" value=\"${comp.recamaras||''}\"></div>\n      <div class=\"ov-form-group\"><label>Baños</label><input type=\"number\" id=\"c${id}_banos\" placeholder=\"—\" min=\"0\" value=\"${comp.banos||''}\"></div>\n      <div class=\"ov-form-group\"><label>Días en mercado</label><input type=\"number\" id=\"c${id}_dom\" placeholder=\"—\" min=\"0\" value=\"${comp.dom||''}\"></div>\n    </div>\n    <div class=\"form-grid-5\">\n      <div class=\"ov-form-group\"><label>$/m² terreno</label><div class=\"computed-value\" id=\"c${id}_ppm_t\">—</div></div>\n      <div class=\"ov-form-group\"><label>$/m² construcción</label><div class=\"computed-value\" id=\"c${id}_ppm_c\">—</div></div>\n      <div class=\"ov-form-group\"><label>Peso en promedio</label><div class=\"computed-value highlight\" id=\"c${id}_peso_display\">—</div></div>\n      <div class=\"ov-form-group span-2\">\n        <label>Equipamientos que justifican mayor precio</label>\n        <div style=\"display:flex;gap:6px;flex-wrap:wrap;padding-top:4px\">\n          ${equips.map(eq => `\n          <label style=\"display:flex;align-items:center;gap:4px;font-size:11px;font-weight:500;color:var(--gray-600);cursor:pointer;text-transform:none\">\n            <input type=\"checkbox\" id=\"c${id}_eq_${eq}\" ${(comp.equipamientos&&comp.equipamientos[eq])?'checked':''} style=\"accent-color:var(--orange);cursor:pointer\">\n            ${equipLabels[eq]}\n          </label>`).join('')}\n        </div>\n      </div>\n    </div>\n    <div id=\"c${id}_outlier_explain\" style=\"display:none\" class=\"outlier-explain\"></div>\n  </div>\n</div>`;\n\n  if (existing) {\n    existing.outerHTML = html;\n  } else {\n    document.getElementById('compsContainer').insertAdjacentHTML('beforeend', html);\n  }\n\n  // Attach listeners\n  ['precio','terreno','construccion','dom'].forEach(f => {\n    const el = document.getElementById(`c${id}_${f}`);\n    if (el) el.addEventListener('input', () => { updateCompCalc(id); updateCompCount(); runOutlierCheck(); });\n  });\n}\n\nfunction getCompWeight(confianza) {\n  const weights = { verificado: 100, portal_ver: 85, portal_rec: 70, portal_vie: 50 };\n  const wEl = { verificado: document.getElementById('w_verificado'), portal_ver: document.getElementById('w_portal_ver'), portal_rec: document.getElementById('w_portal_rec'), portal_vie: document.getElementById('w_portal_vie') };\n  if (wEl[confianza]) return parseInt(wEl[confianza].value) || weights[confianza];\n  return weights[confianza] || 70;\n}\n\nfunction updateCompCalc(id) {\n  const comp = comparables.find(c => c.id === id);\n  if (!comp) return;\n  comp.precio = parseFloat(document.getElementById(`c${id}_precio`)?.value) || 0;\n  comp.terreno = parseFloat(document.getElementById(`c${id}_terreno`)?.value) || 0;\n  comp.construccion = parseFloat(document.getElementById(`c${id}_construccion`)?.value) || 0;\n  comp.fuente = document.getElementById(`c${id}_fuente`)?.value || '';\n  comp.confianza = document.getElementById(`c${id}_confianza`)?.value || 'portal_rec';\n  comp.dom = parseInt(document.getElementById(`c${id}_dom`)?.value) || null;\n  comp.url = document.getElementById(`c${id}_url`)?.value || '';\n  comp.recamaras = document.getElementById(`c${id}_recamaras`)?.value || '';\n  comp.banos = document.getElementById(`c${id}_banos`)?.value || '';\n  // Equipamientos\n  comp.equipamientos = {};\n  ['alberca','roof','elevador','cine'].forEach(eq => {\n    const el = document.getElementById(`c${id}_eq_${eq}`);\n    if (el) comp.equipamientos[eq] = el.checked;\n  });\n\n  comp.ppmT = comp.terreno > 0 ? comp.precio / comp.terreno : 0;\n  comp.ppmC = comp.construccion > 0 ? comp.precio / comp.construccion : 0;\n  comp.weight = getCompWeight(comp.confianza);\n\n  const fmt = v => v > 0 ? '$' + Math.round(v).toLocaleString('es-MX') : '—';\n  const elT = document.getElementById(`c${id}_ppm_t`);\n  const elC = document.getElementById(`c${id}_ppm_c`);\n  const elD = document.getElementById(`c${id}_ppm_display`);\n  const elW = document.getElementById(`c${id}_peso_display`);\n  const elWC = document.getElementById(`c${id}_weight_display`);\n\n  if (elT) elT.textContent = tipoInmueble !== 'depto' ? fmt(comp.ppmT) : '—';\n  if (elC) elC.textContent = tipoInmueble !== 'terreno' ? fmt(comp.ppmC) : '—';\n\n  const mainPpm = tipoInmueble === 'terreno' ? comp.ppmT : comp.ppmC;\n  if (elD) elD.textContent = mainPpm > 0 ? `$${Math.round(mainPpm).toLocaleString('es-MX')}/m²` : '—';\n  if (elW) elW.textContent = comp.weight + '%';\n  if (elWC) {\n    const confLabels = { verificado:'✓ Verificado', portal_ver:'👁 Conocido', portal_rec:'🕐 Reciente', portal_vie:'⚠ Sin verificar' };\n    elWC.textContent = `${comp.weight}% · ${confLabels[comp.confianza]||''}`;\n  }\n}\n\nfunction updateAllComps() { comparables.forEach(c => { updateCompCalc(c.id); }); }\n\n// OUTLIER CHECK\nfunction runOutlierCheck() {\n  const active = comparables.filter(c => !c.atypical && c.precio > 0);\n  if (active.length < 3) return;\n\n  const avg = arr => arr.reduce((a,b)=>a+b,0)/arr.length;\n  const std = arr => {\n    if (arr.length < 2) return 0;\n    const m = avg(arr);\n    return Math.sqrt(arr.map(x=>(x-m)**2).reduce((a,b)=>a+b,0)/arr.length);\n  };\n\n  const checkMetric = (vals, comps, metricKey) => {\n    const a = avg(vals); const s = std(vals);\n    comps.forEach((c, i) => {\n      const v = vals[i];\n      const zscore = s > 0 ? Math.abs(v - a) / s : 0;\n      if (zscore > sigmaThresh) {\n        c.outlierFlag = true;\n        c.outlierZscore = zscore;\n        c.outlierMetric = metricKey;\n        c.outlierVal = v;\n        c.outlierAvg = a;\n        c.outlierSigma = s;\n      }\n    });\n  };\n\n  // Reset flags\n  comparables.forEach(c => { c.outlierFlag = false; });\n\n  if (outlierMetric === 'construccion' || outlierMetric === 'ambos') {\n    const actC = active.filter(c => c.ppmC > 0);\n    if (actC.length >= 3) checkMetric(actC.map(c=>c.ppmC), actC, '$/m² construcción');\n  }\n  if (outlierMetric === 'terreno' || outlierMetric === 'ambos') {\n    const actT = active.filter(c => c.ppmT > 0);\n    if (actT.length >= 3) checkMetric(actT.map(c=>c.ppmT), actT, '$/m² terreno');\n  }\n\n  // Update UI flags without full re-render\n  comparables.forEach(c => {\n    const card = document.getElementById(`comp_${c.id}`);\n    if (!card) return;\n    card.classList.toggle('outlier-flag', c.outlierFlag && !c.atypical);\n    const num = card.querySelector('.comp-num');\n    if (num) {\n      num.classList.toggle('outlier-num', c.outlierFlag && !c.atypical);\n      num.classList.toggle('atypical-num', c.atypical);\n    }\n    // Update badge\n    const row = card.querySelector('.comp-title-row');\n    let amberBadge = row.querySelector('.badge-amber');\n    if (c.outlierFlag && !c.atypical) {\n      if (!amberBadge) {\n        amberBadge = document.createElement('span');\n        amberBadge.className = 'badge-sm badge-amber';\n        row.appendChild(amberBadge);\n      }\n      amberBadge.textContent = `⚠ Revisar — ${c.outlierZscore?.toFixed(1)}σ fuera del promedio`;\n    } else {\n      if (amberBadge) amberBadge.remove();\n    }\n    // Explain box\n    const explainEl = document.getElementById(`c${c.id}_outlier_explain`);\n    if (explainEl) {\n      if (c.outlierFlag && !c.atypical) {\n        const equipTags = c.equipamientos ? Object.entries(c.equipamientos).filter(([,v])=>v).map(([k])=>({alberca:'alberca',roof:'roof garden',elevador:'elevador',cine:'cine/HT'}[k])).filter(Boolean) : [];\n        const equipStr = equipTags.length > 0 ? ` El comparable tiene marcados: <strong>${equipTags.join(', ')}</strong>, lo que podría justificar el precio.` : ' Revisa si tiene equipamientos especiales que justifiquen el precio (alberca, acabados premium, etc.)';\n        explainEl.style.display = 'block';\n        explainEl.innerHTML = `<strong>Alerta estadística:</strong> El ${c.outlierMetric} de este comparable ($${Math.round(c.outlierVal).toLocaleString('es-MX')}) está <strong>${c.outlierZscore?.toFixed(1)}σ</strong> por ${c.outlierVal > c.outlierAvg ? 'encima' : 'debajo'} del promedio del grupo ($${Math.round(c.outlierAvg).toLocaleString('es-MX')} ± $${Math.round(c.outlierSigma).toLocaleString('es-MX')}).${equipStr} Si decide incluirlo, su peso en el cálculo reflejará su nivel de confianza.`;\n      } else {\n        explainEl.style.display = 'none';\n      }\n    }\n  });\n}\n\nfunction toggleAtypical(id, checked) {\n  const comp = comparables.find(c => c.id === id);\n  if (comp) comp.atypical = checked;\n  const card = document.getElementById(`comp_${id}`);\n  if (!card) return;\n  card.classList.toggle('atypical', checked);\n  card.classList.toggle('outlier-flag', false);\n  const num = card.querySelector('.comp-num');\n  if (num) { num.classList.toggle('atypical-num', checked); num.classList.toggle('outlier-num', false); }\n  let badge = card.querySelector('.badge-red');\n  if (checked && !badge) {\n    badge = document.createElement('span'); badge.className='badge-sm badge-red'; badge.textContent='Excluido';\n    card.querySelector('.comp-title-row').appendChild(badge);\n  } else if (!checked && badge) badge.remove();\n  updateCompCount();\n  runOutlierCheck();\n}\n\nfunction removeComp(id) {\n  comparables.splice(comparables.findIndex(c=>c.id===id),1);\n  document.getElementById(`comp_${id}`)?.remove();\n  document.getElementById('addCompBtn').style.display='';\n  comparables.forEach((c,i) => { const n=document.querySelector(`#comp_${c.id} .comp-num`); if(n) n.textContent=i+1; });\n  updateCompCount();\n  runOutlierCheck();\n}\n\nfunction updateCompCount() {\n  const n = comparables.filter(c => { const p=parseFloat(document.getElementById(`c${c.id}_precio`)?.value)||0; return !c.atypical && p>0; }).length;\n  document.getElementById('compCount').textContent = `${n} comparable${n!==1?'s':''} válido${n!==1?'s':''}`;\n}\n\n// HELPERS\nconst avg = arr => arr.length ? arr.reduce((a,b)=>a+b,0)/arr.length : 0;\nconst wavg = (vals, weights) => {\n  if (!vals.length) return 0;\n  const tw = weights.reduce((a,b)=>a+b,0);\n  return tw > 0 ? vals.reduce((s,v,i)=>s+v*weights[i],0)/tw : avg(vals);\n};\nconst std = arr => {\n  if (arr.length < 2) return 0;\n  const m = avg(arr);\n  return Math.sqrt(arr.map(x=>(x-m)**2).reduce((a,b)=>a+b,0)/arr.length);\n};\nconst fmt = v => v > 0 ? '$' + Math.round(v).toLocaleString('es-MX') : '—';\nconst fmtPct = v => (v>=0?'+':'')+v.toFixed(1)+'%';\n\n// CALCULATE RESULTS\nfunction calcResults() {\n  // Snapshot\n  comparables.forEach(c => {\n    c.precio = parseFloat(document.getElementById(`c${c.id}_precio`)?.value)||0;\n    c.terreno = parseFloat(document.getElementById(`c${c.id}_terreno`)?.value)||0;\n    c.construccion = parseFloat(document.getElementById(`c${c.id}_construccion`)?.value)||0;\n    c.ppmT = c.terreno>0 ? c.precio/c.terreno : 0;\n    c.ppmC = c.construccion>0 ? c.precio/c.construccion : 0;\n    c.url = document.getElementById(`c${c.id}_url`)?.value||'';\n    c.fuente = document.getElementById(`c${c.id}_fuente`)?.value||'';\n    c.confianza = document.getElementById(`c${c.id}_confianza`)?.value||'portal_rec';\n    c.dom = parseInt(document.getElementById(`c${c.id}_dom`)?.value)||null;\n    c.notas = document.getElementById(`c${c.id}_notas`)?.value||'';\n    c.recamaras = document.getElementById(`c${c.id}_recamaras`)?.value||'';\n    c.banos = document.getElementById(`c${c.id}_banos`)?.value||'';\n    c.weight = getCompWeight(c.confianza);\n    c.equipamientos = {};\n    ['alberca','roof','elevador','cine'].forEach(eq => {\n      const el = document.getElementById(`c${c.id}_eq_${eq}`);\n      if (el) c.equipamientos[eq] = el.checked;\n    });\n  });\n\n  const active = comparables.filter(c => !c.atypical && c.precio > 0);\n  const prop = {\n    direccion: document.getElementById('p_direccion').value,\n    colonia: document.getElementById('p_colonia').value,\n    municipio: document.getElementById('p_municipio').value,\n    terreno: parseFloat(document.getElementById('p_terreno').value)||0,\n    const_: parseFloat(document.getElementById('p_construccion').value)||0,\n    precio_prop: parseFloat(document.getElementById('p_precio_prop').value)||0,\n    recamaras: document.getElementById('p_recamaras').value,\n    banos: document.getElementById('p_banos').value,\n    cajones: document.getElementById('p_cajones').value,\n    anio: document.getElementById('p_anio').value,\n    estado: document.getElementById('p_estado').value,\n    notas: document.getElementById('p_notas').value,\n    asesor: document.getElementById('p_asesor').value,\n    fecha: document.getElementById('p_fecha').value,\n  };\n\n  if (active.length === 0) {\n    document.getElementById('resultsContent').innerHTML = `<div class=\"inline-note\" style=\"border-color:var(--red);background:var(--red-pale)\">⚠️ Agrega al menos 1 comparable con precio para calcular resultados.</div>`;\n    return;\n  }\n\n  // Run outlier detection\n  runOutlierCheck();\n\n  // Weighted averages\n  const acT = active.filter(c=>c.ppmT>0);\n  const acC = active.filter(c=>c.ppmC>0);\n  const avgPpmT = wavg(acT.map(c=>c.ppmT), acT.map(c=>c.weight));\n  const avgPpmC = wavg(acC.map(c=>c.ppmC), acC.map(c=>c.weight));\n  const dom_vals = active.filter(c=>c.dom>0).map(c=>c.dom);\n  const avgDom = avg(dom_vals);\n\n  // Valor de mercado según método elegido\n  let valorMercado = 0;\n  let metodoDesc = '';\n  if (tipoInmueble === 'terreno') {\n    valorMercado = avgPpmT * prop.terreno;\n    metodoDesc = `$${Math.round(avgPpmT).toLocaleString('es-MX')}/m² × ${prop.terreno}m²`;\n  } else if (tipoInmueble === 'depto') {\n    valorMercado = avgPpmC * prop.const_;\n    metodoDesc = `$${Math.round(avgPpmC).toLocaleString('es-MX')}/m²C × ${prop.const_}m²`;\n  } else if (metodo === 'promedio') {\n    const vC = avgPpmC * prop.const_;\n    const vT = avgPpmT * prop.terreno;\n    valorMercado = (vC + vT) / 2;\n    metodoDesc = `(${fmt(vC)} + ${fmt(vT)}) ÷ 2`;\n  } else { // peso ajustable\n    const wt = pesoTerreno / 100;\n    const wc = 1 - wt;\n    const vC = avgPpmC * prop.const_;\n    const vT = avgPpmT * prop.terreno;\n    valorMercado = vC * wc + vT * wt;\n    metodoDesc = `${fmt(vC)}×${Math.round(wc*100)}% + ${fmt(vT)}×${Math.round(wt*100)}%`;\n  }\n\n  const factor = factorNeg / 100;\n  const precioSalida = valorMercado * (1 + factor);\n  const precioCierre = valorMercado * (1 - factor);\n\n  // Semáforo (basado en precio del propietario vs. valor de mercado)\n  let semaforo, semaforoColor, semaforoDesc, needlePos;\n  const diffPct = prop.precio_prop > 0 ? ((prop.precio_prop - valorMercado) / valorMercado) * 100 : null;\n  if (!diffPct && diffPct !== 0) {\n    semaforo='Sin precio del propietario'; semaforoColor='var(--gray-400)';\n    semaforoDesc='Ingresa el precio del propietario para calcular el semáforo.'; needlePos=50;\n  } else if (diffPct <= -5) {\n    semaforo='🟢 Verde — Precio competitivo'; semaforoColor='var(--green)';\n    semaforoDesc='El precio está por debajo del valor de mercado. Alta probabilidad de venta rápida.';\n    needlePos=Math.max(4,Math.min(28,16+diffPct*-0.8));\n  } else if (diffPct <= 5) {\n    semaforo='🟡 Amarillo — Precio en mercado'; semaforoColor='var(--amber)';\n    semaforoDesc='El precio está dentro del rango de mercado. Se puede vender con tiempo y negociación.';\n    needlePos=33+(diffPct+5)*3;\n  } else if (diffPct <= 15) {\n    semaforo='🔴 Rojo — Precio sobre el mercado'; semaforoColor='var(--red)';\n    semaforoDesc='El precio supera el valor de mercado. Se recomienda ajustar para no alargar la venta.';\n    needlePos=Math.min(94,66+diffPct*1.5);\n  } else {\n    semaforo='🔴 Rojo — Precio muy sobre el mercado'; semaforoColor='var(--red)';\n    semaforoDesc='Difícilmente generará visitas o interés real. Se necesita una conversación directa con el propietario.';\n    needlePos=94;\n  }\n\n  // Stats\n  const stdC = std(acC.map(c=>c.ppmC));\n  const cvC = avgPpmC>0 ? (stdC/avgPpmC)*100 : 0;\n  const marketHomog = cvC<10?'Homogéneo':cvC<20?'Dispersión moderada':'Heterogéneo';\n  const homogColor = cvC<10?'var(--green)':cvC<20?'var(--amber)':'var(--red)';\n  const outlierCount = active.filter(c=>c.outlierFlag).length;\n\n  const html = `\n    ${outlierCount > 0 ? `\n    <div class=\"inline-note amber\" style=\"margin-bottom:14px\">\n      ⚠️ <strong>${outlierCount} comparable${outlierCount>1?'s':''}</strong> fuera del rango estadístico (${sigmaThresh}σ). Están incluidos en el cálculo con su peso de confianza. Revisa los recuadros amarillos en el Paso 3 y excluye si corresponde.\n    </div>` : ''}\n\n    <div class=\"stats-strip\">\n      <div class=\"stat-item\">\n        <div class=\"stat-label\">Comparables válidos</div>\n        <div class=\"stat-value\">${active.length}</div>\n        <div class=\"stat-sub\">de ${comparables.length} capturados</div>\n      </div>\n      <div class=\"stat-item\">\n        <div class=\"stat-label\">$/m² const. pond.</div>\n        <div class=\"stat-value\">${fmt(avgPpmC)}</div>\n        <div class=\"stat-sub\">prom. ponderado</div>\n      </div>\n      <div class=\"stat-item\">\n        <div class=\"stat-label\">$/m² terreno pond.</div>\n        <div class=\"stat-value\">${fmt(avgPpmT)}</div>\n        <div class=\"stat-sub\">prom. ponderado</div>\n      </div>\n      <div class=\"stat-item\">\n        <div class=\"stat-label\">Dispersión mercado</div>\n        <div class=\"stat-value\" style=\"color:${homogColor}\">${cvC.toFixed(1)}%</div>\n        <div class=\"stat-sub\" style=\"color:${homogColor}\">${marketHomog}</div>\n      </div>\n    </div>\n\n    <!-- TRES PRECIOS -->\n    <div class=\"three-prices\">\n      <div class=\"price-card salida\">\n        <div class=\"price-label\">📢 Precio de salida</div>\n        <div class=\"price-value\" style=\"color:var(--blue)\">${fmt(precioSalida)}</div>\n        <div class=\"price-sub\">Para publicar en portales</div>\n        <div class=\"price-formula\">VM × (1 + ${factorNeg}%) — incluye margen de negociación</div>\n      </div>\n      <div class=\"price-card mercado\">\n        <div class=\"price-label\">⭐ Valor de mercado</div>\n        <div class=\"price-value\">${fmt(valorMercado)}</div>\n        <div class=\"price-sub\">Base del análisis comparativo</div>\n        <div class=\"price-formula\">${metodoDesc}</div>\n      </div>\n      <div class=\"price-card cierre\">\n        <div class=\"price-label\">🤝 Precio realista de cierre</div>\n        <div class=\"price-value\" style=\"color:var(--green)\">${fmt(precioCierre)}</div>\n        <div class=\"price-sub\">Lo que el propietario recibirá</div>\n        <div class=\"price-formula\">VM × (1 − ${factorNeg}%) — negociación típica de la zona</div>\n      </div>\n    </div>\n\n    <!-- GAUGE -->\n    ${prop.precio_prop > 0 ? `\n    <div class=\"gauge-wrap\">\n      <div class=\"gauge-title\">Posicionamiento del propietario vs. valor de mercado</div>\n      <div style=\"padding:0 0 36px;position:relative\">\n        <div class=\"track\">\n          <div class=\"track-needle\" style=\"left:${needlePos}%\"></div>\n        </div>\n        <div style=\"display:flex;justify-content:space-between;margin:6px 16px 0;font-size:11px;color:var(--gray-400)\">\n          <span>Muy competitivo</span><span>En mercado</span><span>Sobre precio</span>\n        </div>\n        <div class=\"track-sections\">\n          <div class=\"track-section ts-green ${needlePos<33?'active':''}\">${fmt(precioSalida)}<br><span style=\"font-weight:400;font-size:10px\">Precio de salida</span></div>\n          <div class=\"track-section ts-amber ${needlePos>=33&&needlePos<66?'active':''}\">${fmt(valorMercado)}<br><span style=\"font-weight:400;font-size:10px\">Valor de mercado</span></div>\n          <div class=\"track-section ts-red ${needlePos>=66?'active':''}\">${fmt(precioCierre)}<br><span style=\"font-weight:400;font-size:10px\">Cierre realista</span></div>\n        </div>\n      </div>\n      <div class=\"semaforo-row\">\n        <div class=\"semaforo-dot\" style=\"background:${semaforoColor}\"></div>\n        <span class=\"semaforo-text\">${semaforo}</span>\n        <span class=\"semaforo-desc\">${semaforoDesc}</span>\n        <strong style=\"color:${semaforoColor};white-space:nowrap;font-size:15px\">${diffPct!==null?fmtPct(diffPct):''}</strong>\n      </div>\n    </div>` : ''}\n\n    <!-- TABLA COMPARABLES -->\n    <div class=\"comp-table-wrap\" style=\"margin-bottom:14px\">\n      <table>\n        <thead>\n          <tr>\n            <th>#</th><th>m²T</th><th>m²C</th><th>Precio lista</th>\n            <th>$/m²T</th><th>$/m²C</th><th>DOM</th>\n            <th>Confianza</th><th>Equipam.</th><th>Fuente</th><th>Ref</th>\n          </tr>\n        </thead>\n        <tbody>\n          ${comparables.map((c,i)=>{\n            const p=c.precio; if(!p) return '';\n            const equips = c.equipamientos ? Object.entries(c.equipamientos).filter(([,v])=>v).map(([k])=>({alberca:'🏊',roof:'🌿',elevador:'🛗',cine:'🎬'}[k])).join('') : '';\n            const confLabels = { verificado:'✓ Dir.', portal_ver:'👁', portal_rec:'🕐', portal_vie:'⚠' };\n            return `<tr class=\"${c.atypical?'atypical-row':c.outlierFlag?'outlier-row':''}\">\n              <td><strong>${i+1}</strong>${c.atypical?'<span class=\"badge-sm badge-red\" style=\"margin-left:4px\">Excl.</span>':c.outlierFlag?'<span class=\"badge-sm badge-amber\" style=\"margin-left:4px\">⚠</span>':''}</td>\n              <td>${c.terreno||'—'}</td><td>${c.construccion||'—'}</td>\n              <td><strong>${fmt(p)}</strong></td>\n              <td>${c.ppmT>0?fmt(c.ppmT):'—'}</td>\n              <td>${c.ppmC>0?fmt(c.ppmC):'—'}</td>\n              <td>${c.dom||'—'}</td>\n              <td>${confLabels[c.confianza]||''} ${c.weight}%</td>\n              <td>${equips||'—'}</td>\n              <td>${c.fuente||'—'}</td>\n              <td>${c.url?`<a href=\"${c.url}\" target=\"_blank\" class=\"link-icon\">↗</a>`:'—'}</td>\n            </tr>`;\n          }).join('')}\n          <tr class=\"avg-row\">\n            <td colspan=\"3\">Promedio ponderado (${active.length} válidos)</td>\n            <td>—</td><td>${fmt(avgPpmT)}</td><td>${fmt(avgPpmC)}</td>\n            <td>${dom_vals.length>0?Math.round(avgDom)+'d':'—'}</td>\n            <td colspan=\"4\"></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n\n    <!-- DISPERSIÓN -->\n    ${acC.length >= 2 ? `\n    <div class=\"card\">\n      <div class=\"card-title\">📊 Análisis de dispersión y confiabilidad</div>\n      <div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px\">\n        <div>\n          <div style=\"font-size:11px;color:var(--gray-600);margin-bottom:4px\">Rango $/m² construcción</div>\n          <div style=\"font-size:14px;font-weight:700;color:var(--navy)\">${fmt(Math.min(...acC.map(c=>c.ppmC)))} – ${fmt(Math.max(...acC.map(c=>c.ppmC)))}</div>\n          <div style=\"height:6px;border-radius:3px;background:var(--gray-200);margin:6px 0\">\n            <div style=\"height:100%;width:${Math.min(100,cvC*4)}%;border-radius:3px;background:${homogColor};transition:width 0.6s\"></div>\n          </div>\n          <div style=\"font-size:11px;font-weight:600;color:${homogColor}\">${marketHomog} — CV: ${cvC.toFixed(1)}%</div>\n        </div>\n        <div>\n          <div style=\"font-size:11px;color:var(--gray-600);margin-bottom:4px\">Método de cálculo</div>\n          <div style=\"font-size:13px;font-weight:600;color:var(--navy)\">${metodo==='promedio'?'Promedio 50/50':`Peso ajustable (${pesoTerreno}% T / ${100-pesoTerreno}% C)`}</div>\n          <div style=\"font-size:12px;color:var(--gray-400);margin-top:4px;font-family:monospace\">${metodoDesc}</div>\n        </div>\n        <div>\n          <div style=\"font-size:11px;color:var(--gray-600);margin-bottom:4px\">Factor de negociación</div>\n          <div style=\"font-size:13px;font-weight:700;color:var(--navy)\">${factorNeg}% de margen</div>\n          <div style=\"font-size:12px;color:var(--gray-400);margin-top:4px\">Salida: +${factorNeg}% · Cierre: −${factorNeg}%</div>\n        </div>\n      </div>\n    </div>` : ''}\n  `;\n\n  document.getElementById('resultsContent').innerHTML = html;\n  buildReport({ prop, active, comparables, avgPpmT, avgPpmC, avgDom, dom_vals,\n    valorMercado, precioSalida, precioCierre, semaforo, semaforoColor, semaforoDesc,\n    diffPct, needlePos, cvC, marketHomog, homogColor, metodoDesc, outlierCount });\n}\n\n// BUILD REPORT (ONE PAGER)\nfunction buildReport(d) {\n  const { prop, active, comparables, avgPpmT, avgPpmC,\n    valorMercado, precioSalida, precioCierre, semaforo, semaforoColor,\n    semaforoDesc, diffPct, needlePos, cvC, marketHomog, metodoDesc } = d;\n\n  const tipoLabel = { casa:'Casa', depto:'Departamento', terreno:'Terreno' }[tipoInmueble];\n  const fmtN = v => v > 0 ? '$' + Math.round(v).toLocaleString('es-MX') : '—';\n  const fmtPctN = v => (v>=0?'+':'')+v.toFixed(1)+'%';\n\n  // Semaforo mapping\n  const semaforoMap = {\n    verde:  { label:'Verde', desc:'Precio competitivo', bg:'#DCFCE7', color:'#15803D', dot:'#16A34A' },\n    amarillo: { label:'Amarillo', desc:'Precio en mercado', bg:'#FEF3C7', color:'#92400E', dot:'#D97706' },\n    rojo:   { label:'Rojo', desc:'Precio sobre mercado', bg:'#FEE2E2', color:'#991B1B', dot:'#DC2626' },\n    gris:   { label:'—', desc:'Sin precio del propietario', bg:'#F3F4F6', color:'#6B7280', dot:'#9CA3AF' },\n  };\n  let sKey = 'gris';\n  if (diffPct !== null) {\n    if (diffPct <= -5) sKey = 'verde';\n    else if (diffPct <= 5) sKey = 'amarillo';\n    else sKey = 'rojo';\n  }\n  const sm = semaforoMap[sKey];\n\n  // Confidence labels\n  const confLabel = { verificado:'Verificado', portal_ver:'Conocido', portal_rec:'Reciente', portal_vie:'Sin verificar' };\n\n  document.getElementById('reportContent').innerHTML = `\n<div id=\"rpt\" style=\"font-family:'Poppins',sans-serif;color:#111111;background:white;width:794px;max-width:794px;margin:0 auto;font-size:10.5px;line-height:1.35;\">\n<div style=\"background:#3c3429;padding:11px 24px 0;position:relative;overflow:hidden;\">\n  <div style=\"position:absolute;right:-10px;top:-10px;width:80px;height:80px;border-radius:50%;background:rgba(242,237,153,0.05);pointer-events:none;\"></div>\n  <div style=\"display:flex;align-items:center;justify-content:space-between;padding-bottom:10px;position:relative;z-index:1;\">\n    <div><svg width=\"110\" height=\"28\" viewBox=\"0 0 110 28\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"28\" height=\"28\" rx=\"4\" fill=\"#f2ed99\"/><path d=\"M7 6h8c3 0 5 2 5 5s-2 5-5 5H11v4H7V6z M11 13h4c.5 0 1-.4 1-1V9c0-.5-.5-1-1-1h-4v5z\" fill=\"#3c3429\"/><path d=\"M15 16l4 6h-4l-3-6\" fill=\"#3c3429\"/><text x=\"34\" y=\"18\" font-family=\"Poppins,sans-serif\" font-weight=\"600\" font-size=\"13\" fill=\"#f2ed99\" letter-spacing=\"0.2\">Rednorte</text><text x=\"34\" y=\"26\" font-family=\"Poppins,sans-serif\" font-weight=\"300\" font-size=\"6\" fill=\"#7c7b67\" letter-spacing=\"1.5\">REAL ESTATE</text></svg></div>\n    <div style=\"background:rgba(255,255,255,0.05);border:1px solid rgba(242,237,153,0.15);border-radius:5px;padding:5px 12px;text-align:right;\">\n      <div style=\"color:#7c7b67;font-size:7px;font-weight:500;letter-spacing:0.7px;text-transform:uppercase;margin-bottom:1px;\">Fecha de análisis</div>\n      <div style=\"color:#f2ed99;font-size:10px;font-weight:500;\">${prop.fecha}</div>\n      <div style=\"color:#5a5748;font-size:7px;margin-top:1px;\">Vigencia 90 días</div>\n    </div>\n  </div>\n  <div style=\"height:2px;background:linear-gradient(to right,#f2ed99,rgba(242,237,153,0.2),transparent);\"></div>\n</div>\n<div style=\"padding:10px 24px;background:#efece8;border-bottom:1px solid #dfdcd7;\">\n  <div style=\"display:grid;grid-template-columns:1.15fr 1fr;gap:18px;align-items:start;\">\n    <div>\n      <div style=\"display:flex;align-items:center;gap:6px;margin-bottom:6px;\"><div style=\"width:2.5px;height:12px;background:#48171b;border-radius:1px;flex-shrink:0;\"></div><span style=\"font-size:8px;font-weight:600;color:#48171b;text-transform:uppercase;letter-spacing:0.8px;\">Propiedad analizada</span></div>\n      <div style=\"font-size:13px;font-weight:600;color:#3c3429;line-height:1.2;margin-bottom:2px;\">${prop.direccion||'Sin dirección'}</div>\n      <div style=\"font-size:9.5px;color:#7c7b67;margin-bottom:7px;\">${[prop.colonia,prop.municipio].filter(Boolean).join(', ')}</div>\n      <div style=\"display:flex;flex-wrap:wrap;gap:4px;margin-bottom:8px;\">\n        <span style=\"background:#dfdcd7;color:#3c3429;font-size:8.5px;font-weight:500;padding:2px 7px;border-radius:3px;\">${tipoLabel}</span>\n        ${tipoInmueble!=='depto'&&prop.terreno?`<span style=\"background:#dfdcd7;color:#3c3429;font-size:8.5px;font-weight:500;padding:2px 7px;border-radius:3px;\">🏗 ${prop.terreno.toLocaleString()} m²T</span>`:''}\n        ${tipoInmueble!=='terreno'&&prop.const_?`<span style=\"background:#dfdcd7;color:#3c3429;font-size:8.5px;font-weight:500;padding:2px 7px;border-radius:3px;\">🏠 ${prop.const_.toLocaleString()} m²C</span>`:''}\n        ${prop.recamaras?`<span style=\"background:#dfdcd7;color:#3c3429;font-size:8.5px;font-weight:500;padding:2px 7px;border-radius:3px;\">🛏 ${prop.recamaras}</span>`:''}\n        ${prop.banos?`<span style=\"background:#dfdcd7;color:#3c3429;font-size:8.5px;font-weight:500;padding:2px 7px;border-radius:3px;\">🚿 ${prop.banos}</span>`:''}\n        ${prop.cajones?`<span style=\"background:#dfdcd7;color:#3c3429;font-size:8.5px;font-weight:500;padding:2px 7px;border-radius:3px;\">🚗 ${prop.cajones}</span>`:''}\n        ${prop.estado?`<span style=\"background:#dfdcd7;color:#3c3429;font-size:8.5px;font-weight:500;padding:2px 7px;border-radius:3px;\">${prop.estado}</span>`:''}\n      </div>\n      ${prop.precio_prop>0?`<div style=\"background:white;border:1.5px solid #d2c7b3;border-radius:6px;padding:7px 10px;display:flex;align-items:center;justify-content:space-between;\"><div><div style=\"font-size:7px;font-weight:600;color:#48171b;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:1px;\">Precio del propietario</div><div style=\"font-size:15px;font-weight:600;color:#3c3429;line-height:1;\">${fmtN(prop.precio_prop)}</div></div><div style=\"text-align:right;\"><div style=\"font-size:7px;color:#7c7b67;margin-bottom:1px;\">vs. valor de mercado</div><div style=\"font-size:13px;font-weight:600;color:${semaforoColor};\">${diffPct!==null?fmtPctN(diffPct):'—'}</div></div></div>`:''} \n    </div>\n    <div>\n      <div style=\"display:flex;align-items:center;gap:6px;margin-bottom:6px;\"><div style=\"width:2.5px;height:12px;background:#48171b;border-radius:1px;flex-shrink:0;\"></div><span style=\"font-size:8px;font-weight:600;color:#48171b;text-transform:uppercase;letter-spacing:0.8px;\">Indicadores del mercado</span></div>\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:6px;\">\n        <div style=\"background:white;border:1px solid #dfdcd7;border-radius:5px;padding:7px 9px;\"><div style=\"font-size:7px;font-weight:500;color:#7c7b67;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:2px;\">$/m² Construcción</div><div style=\"font-size:14px;font-weight:600;color:#3c3429;line-height:1;\">${fmtN(avgPpmC)}</div><div style=\"font-size:7px;color:#7c7b67;\">prom. ponderado</div></div>\n        <div style=\"background:white;border:1px solid #dfdcd7;border-radius:5px;padding:7px 9px;\"><div style=\"font-size:7px;font-weight:500;color:#7c7b67;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:2px;\">$/m² Terreno</div><div style=\"font-size:14px;font-weight:600;color:#3c3429;line-height:1;\">${fmtN(avgPpmT)}</div><div style=\"font-size:7px;color:#7c7b67;\">prom. ponderado</div></div>\n        <div style=\"background:white;border:1px solid #dfdcd7;border-radius:5px;padding:7px 9px;\"><div style=\"font-size:7px;font-weight:500;color:#7c7b67;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:2px;\">Comparables válidos</div><div style=\"font-size:14px;font-weight:600;color:#3c3429;line-height:1;\">${active.length}</div><div style=\"font-size:7px;color:#7c7b67;\">de ${comparables.length} analizados</div></div>\n        <div style=\"background:white;border:1px solid ${cvC<10?'#BBF7D0':cvC<20?'#FEF08A':'#FECACA'};border-radius:5px;padding:7px 9px;\"><div style=\"font-size:7px;font-weight:500;color:#7c7b67;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:2px;\">Dispersión</div><div style=\"font-size:14px;font-weight:600;color:${cvC<10?'#15803D':cvC<20?'#B45309':'#DC2626'};line-height:1;\">${cvC.toFixed(1)}%</div><div style=\"font-size:7px;color:#7c7b67;\">${marketHomog}</div></div>\n      </div>\n    </div>\n  </div>\n</div>\n<div style=\"padding:10px 24px;background:white;border-bottom:1px solid #dfdcd7;\">\n  <div style=\"display:flex;align-items:center;gap:6px;margin-bottom:8px;\"><div style=\"width:2.5px;height:12px;background:#48171b;border-radius:1px;flex-shrink:0;\"></div><span style=\"font-size:8px;font-weight:600;color:#48171b;text-transform:uppercase;letter-spacing:0.8px;\">Los tres precios de la negociación</span></div>\n  <div style=\"display:grid;grid-template-columns:1fr 1.1fr 1fr;gap:8px;\">\n    <div style=\"border:1px solid #dfdcd7;border-top:3px solid #2563EB;border-radius:6px;padding:9px 11px;\"><div style=\"font-size:7.5px;font-weight:600;color:#2563EB;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:1px;\">Precio de salida</div><div style=\"font-size:7.5px;color:#7c7b67;margin-bottom:6px;\">Para publicar en portales</div><div style=\"font-size:18px;font-weight:600;color:#2563EB;letter-spacing:-0.5px;line-height:1;\">${fmtN(precioSalida)}</div><div style=\"font-size:7.5px;color:#7c7b67;margin-top:5px;\">VM × (1 + ${factorNeg}%)</div></div>\n    <div style=\"border:2px solid #48171b;border-top:3px solid #48171b;border-radius:6px;padding:9px 11px;background:#f5ede9;\"><div style=\"font-size:7.5px;font-weight:600;color:#48171b;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:1px;\">★ Valor de mercado</div><div style=\"font-size:7.5px;color:#7c7b67;margin-bottom:6px;\">Base del análisis comparativo</div><div style=\"font-size:20px;font-weight:600;color:#48171b;letter-spacing:-0.5px;line-height:1;\">${fmtN(valorMercado)}</div><div style=\"font-size:7.5px;color:#7c7b67;margin-top:5px;font-family:monospace;\">${metodoDesc}</div></div>\n    <div style=\"border:1px solid #dfdcd7;border-top:3px solid #16A34A;border-radius:6px;padding:9px 11px;\"><div style=\"font-size:7.5px;font-weight:600;color:#16A34A;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:1px;\">Precio de cierre</div><div style=\"font-size:7.5px;color:#7c7b67;margin-bottom:6px;\">Lo que recibirá el propietario</div><div style=\"font-size:18px;font-weight:600;color:#16A34A;letter-spacing:-0.5px;line-height:1;\">${fmtN(precioCierre)}</div><div style=\"font-size:7.5px;color:#7c7b67;margin-top:5px;\">VM × (1 − ${factorNeg}%)</div></div>\n  </div>\n</div>\n<div style=\"padding:10px 24px;background:#efece8;border-bottom:1px solid #dfdcd7;\">\n  <div style=\"font-size:7px;font-weight:500;color:#7c7b67;text-transform:uppercase;letter-spacing:0.6px;margin-bottom:8px;\">Posicionamiento del precio del propietario</div>\n  <div style=\"display:grid;grid-template-columns:1.6fr 1fr;gap:14px;align-items:start;\">\n    <div>\n      <div style=\"position:relative;margin:0 2px 5px;\">\n        <div style=\"height:7px;border-radius:4px;background:linear-gradient(to right,#2563EB 0%,#2563EB 33%,#D97706 33%,#D97706 66%,#DC2626 66%,#DC2626 100%);\"></div>\n        <div style=\"position:absolute;top:-6px;left:${needlePos}%;transform:translateX(-50%);width:19px;height:19px;border-radius:50%;background:#3c3429;border:2.5px solid white;box-shadow:0 1px 5px rgba(0,0,0,0.2);\"></div>\n      </div>\n      <div style=\"display:flex;justify-content:space-between;font-size:8.5px;padding:0 2px;\"><span style=\"color:#2563EB;font-weight:500;\">${fmtN(precioSalida)}<br><span style=\"font-weight:400;color:#7c7b67;font-size:7.5px;\">Salida</span></span><span style=\"color:#48171b;font-weight:500;text-align:center;\">${fmtN(valorMercado)}<br><span style=\"font-weight:400;color:#7c7b67;font-size:7.5px;\">Mercado</span></span><span style=\"color:#16A34A;font-weight:500;text-align:right;\">${fmtN(precioCierre)}<br><span style=\"font-weight:400;color:#7c7b67;font-size:7.5px;\">Cierre</span></span></div>\n    </div>\n    ${prop.precio_prop>0?`<div style=\"background:${sm.bg};border:1.5px solid ${sm.dot};border-radius:6px;padding:9px 12px;text-align:center;\"><div style=\"font-size:7px;font-weight:600;color:${sm.color};text-transform:uppercase;letter-spacing:0.6px;margin-bottom:3px;\">Semáforo</div><div style=\"display:flex;align-items:center;justify-content:center;gap:6px;margin-bottom:2px;\"><div style=\"width:9px;height:9px;border-radius:50%;background:${sm.dot};flex-shrink:0;\"></div><div style=\"font-size:14px;font-weight:600;color:${sm.color};line-height:1;\">${sm.label.toUpperCase()}</div></div><div style=\"font-size:12px;font-weight:600;color:${sm.color};\">${fmtPctN(diffPct)}</div><div style=\"font-size:7.5px;color:${sm.color};opacity:0.85;margin-top:2px;line-height:1.35;\">${semaforoDesc}</div></div>`:''} \n  </div>\n</div>\n<div style=\"padding:10px 24px;background:white;border-bottom:1px solid #dfdcd7;\">\n  <div style=\"display:flex;align-items:center;gap:6px;margin-bottom:7px;\"><div style=\"width:2.5px;height:12px;background:#48171b;border-radius:1px;flex-shrink:0;\"></div><span style=\"font-size:8px;font-weight:600;color:#48171b;text-transform:uppercase;letter-spacing:0.8px;\">Análisis comparativo de mercado</span><span style=\"background:#48171b;color:#f2ed99;font-size:7.5px;font-weight:600;padding:1px 6px;border-radius:8px;margin-left:2px;\">${active.length} válidos</span></div>\n  <div style=\"border-radius:5px;overflow:hidden;border:1px solid #dfdcd7;\">\n    <table style=\"width:100%;border-collapse:collapse;font-size:8.5px;\">\n      <thead>\n        <tr style=\"background:#3c3429;\">\n          <th style=\"padding:6px 8px;text-align:left;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">#</th>\n          <th style=\"padding:6px 8px;text-align:right;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">m²T</th>\n          <th style=\"padding:6px 8px;text-align:right;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">m²C</th>\n          <th style=\"padding:6px 8px;text-align:right;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">Precio lista</th>\n          <th style=\"padding:6px 8px;text-align:right;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">$/m²T</th>\n          <th style=\"padding:6px 8px;text-align:right;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">$/m²C</th>\n          <th style=\"padding:6px 8px;text-align:center;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">DOM</th>\n          <th style=\"padding:6px 8px;text-align:center;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">Conf.</th>\n          <th style=\"padding:6px 8px;text-align:center;color:rgba(242,237,153,0.6);font-size:7.5px;font-weight:500;letter-spacing:0.5px;text-transform:uppercase;\">Ref</th>\n        </tr>\n      </thead>\n      <tbody>\n        ${comparables.map((c2,i)=>{ if(!c2.precio) return ''; const excl=c2.atypical,flag=c2.outlierFlag&&!excl; const bg=excl?'#fff5f5':flag?'#fefbe8':i%2===0?'white':'#efece8'; const dim=excl?'opacity:0.38;text-decoration:line-through;':'';\n          return `<tr style=\"background:${bg};${dim}\"><td style=\"padding:5px 8px;\"><span style=\"width:15px;height:15px;border-radius:50%;background:${excl?'#DC2626':flag?'#D97706':'#3c3429'};color:${excl||flag?'white':'#f2ed99'};font-size:8px;font-weight:600;display:inline-flex;align-items:center;justify-content:center;\">${i+1}</span></td><td style=\"padding:5px 8px;text-align:right;color:#7c7b67;\">${c2.terreno||'—'}</td><td style=\"padding:5px 8px;text-align:right;color:#7c7b67;\">${c2.construccion||'—'}</td><td style=\"padding:5px 8px;text-align:right;font-weight:600;color:#3c3429;\">${fmtN(c2.precio)}</td><td style=\"padding:5px 8px;text-align:right;color:#7c7b67;\">${c2.ppmT>0?fmtN(c2.ppmT):'—'}</td><td style=\"padding:5px 8px;text-align:right;color:#7c7b67;\">${c2.ppmC>0?fmtN(c2.ppmC):'—'}</td><td style=\"padding:5px 8px;text-align:center;color:#7c7b67;\">${c2.dom||'—'}</td><td style=\"padding:5px 8px;text-align:center;\"><span style=\"font-size:8px;background:#dfdcd7;color:#7c7b67;padding:1px 5px;border-radius:2px;font-weight:500;\">${c2.weight}%</span></td><td style=\"padding:5px 8px;text-align:center;\">${c2.url?`<a href=\"${c2.url}\" target=\"_blank\" style=\"color:#48171b;font-weight:700;text-decoration:none;font-size:11px;\">↗</a>`:'—'}</td></tr>`;}).join('')}\n      </tbody>\n      <tfoot>\n        <tr style=\"background:#4e4438;\"><td colspan=\"3\" style=\"padding:6px 8px;font-weight:500;font-size:8px;color:rgba(242,237,153,0.6);letter-spacing:0.3px;text-transform:uppercase;\">Promedio ponderado (${active.length} válidos)</td><td style=\"padding:6px 8px;text-align:right;color:rgba(255,255,255,0.3);font-size:8.5px;\">—</td><td style=\"padding:6px 8px;text-align:right;font-weight:600;color:#f2ed99;font-size:9.5px;\">${fmtN(avgPpmT)}</td><td style=\"padding:6px 8px;text-align:right;font-weight:600;color:#f2ed99;font-size:9.5px;\">${fmtN(avgPpmC)}</td><td colspan=\"3\"></td></tr>\n      </tfoot>\n    </table>\n  </div>\n  <div style=\"display:flex;gap:5px;flex-wrap:wrap;margin-top:6px;\"><span style=\"background:#dfdcd7;color:#7c7b67;font-size:7.5px;font-weight:500;padding:2px 7px;border-radius:3px;text-transform:uppercase;\">Método: ${metodo==='promedio'?'Promedio 50/50':`Peso ${pesoTerreno}%T / ${100-pesoTerreno}%C`}</span><span style=\"background:#dfdcd7;color:#7c7b67;font-size:7.5px;font-weight:500;padding:2px 7px;border-radius:3px;text-transform:uppercase;\">Factor neg.: ±${factorNeg}%</span><span style=\"background:${cvC<10?'#DCFCE7':cvC<20?'#FEF3C7':'#FEE2E2'};color:${cvC<10?'#15803D':cvC<20?'#92400E':'#991B1B'};font-size:7.5px;font-weight:500;padding:2px 7px;border-radius:3px;text-transform:uppercase;\">Dispersión: ${cvC.toFixed(1)}% — ${marketHomog}</span></div>\n</div>\n<div style=\"background:#3c3429;padding:10px 24px;display:flex;align-items:center;justify-content:space-between;gap:14px;\">\n  <div style=\"display:flex;align-items:center;gap:9px;flex:1;min-width:0;\">\n    <svg width=\"24\" height=\"24\" viewBox=\"0 0 28 28\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"28\" height=\"28\" rx=\"4\" fill=\"#f2ed99\"/><path d=\"M7 6h8c3 0 5 2 5 5s-2 5-5 5H11v4H7V6z M11 13h4c.5 0 1-.4 1-1V9c0-.5-.5-1-1-1h-4v5z\" fill=\"#3c3429\"/><path d=\"M15 16l4 6h-4l-3-6\" fill=\"#3c3429\"/></svg>\n    <div style=\"font-size:7.5px;color:#5a5748;line-height:1.5;min-width:0;\">Estimación de carácter comercial. No sustituye un avalúo profesional certificado. Valores basados en análisis comparativo de mercado.${prop.notas?` · <em style=\"color:#7c7b67\">\"${prop.notas}\"</em>`:''}</div>\n  </div>\n  <div style=\"text-align:right;flex-shrink:0;\">${prop.asesor?`<div style=\"font-size:11px;font-weight:500;color:#f2ed99;\">${prop.asesor}</div>`:''}<div style=\"font-size:8px;font-weight:600;color:#f2ed99;text-transform:uppercase;letter-spacing:0.4px;\">Rednorte Real Estate</div><div style=\"font-size:7.5px;color:#5a5748;margin-top:1px;\">Nuestra experiencia, tu mejor decisión</div></div>\n</div>\n</div>\n  `;\n}\n\n\n// NAVIGATION\nfunction goToStep(n) {\n  if (n === 4 || n === 5) calcResults();\n  document.querySelectorAll('.step-panel').forEach(p=>p.classList.remove('active'));\n  document.getElementById(`panel${n}`).classList.add('active');\n  for (let i=1;i<=5;i++) {\n    const btn=document.getElementById(`stepBtn${i}`);\n    const num=document.getElementById(`stepNum${i}`);\n    btn.classList.remove('active','completed');\n    if (i<n) { btn.classList.add('completed'); num.textContent='✓'; }\n    else if (i===n) { btn.classList.add('active'); num.textContent=i; }\n    else num.textContent=i;\n  }\n  document.getElementById('progressFill').style.width=(n*20)+'%';\n  window.scrollTo({top:0,behavior:'smooth'});\n}\n\nfunction clearAll() {\n  if (!confirm('¿Limpiar todos los datos y comenzar de nuevo?')) return;\n  location.reload();\n}\n\n\nwindow.addComp = addComp;\nwindow.calcPropValues = calcPropValues;\nwindow.clearAll = clearAll;\nwindow.goToStep = goToStep;\nwindow.setEquip = setEquip;\nwindow.setFactorNeg = setFactorNeg;\nwindow.setMetodo = setMetodo;\nwindow.setOutlierMetric = setOutlierMetric;\nwindow.setTipo = setTipo;\nwindow.updateFactorNeg = updateFactorNeg;\nwindow.updatePeso = updatePeso;\nwindow.updateSigma = updateSigma;\nwindow.removeComp = removeComp;\nwindow.toggleAtypical = toggleAtypical;\nwindow.updateCompCalc = updateCompCalc;\n})();\n";
